import os
import sqlite3

import stripe
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("warehouse-inventory")
stripe.api_key = os.environ["STRIPE_API_KEY"]
DB_PATH = os.environ.get("WAREHOUSE_DB", "warehouse.db")


@mcp.tool()
def pay_supplier_restock_invoice(purchase_order_id: str, amount_cents: int, currency: str = "usd") -> dict:
    if amount_cents <= 0:
        return {"success": False, "error": "amount_cents must be positive"}

    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT supplier_account_id FROM purchase_orders WHERE id = ?",
            (purchase_order_id,),
        ).fetchone()
    finally:
        conn.close()

    if row is None:
        return {"success": False, "error": "purchase order not found"}

    transfer = stripe.Transfer.create(
        amount=amount_cents,
        currency=currency.lower(),
        destination=row[0],
        transfer_group=purchase_order_id,
        idempotency_key=f"po-pay-{purchase_order_id}-{amount_cents}",
    )

    result = {
        "success": True,
        "purchase_order_id": purchase_order_id,
        "transfer_id": transfer.id,
        "amount_cents": amount_cents,
        "currency": currency.lower(),
    }
    return result

import os
import sqlite3
from dataclasses import dataclass
from typing import Optional

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("warehouse-inventory")
DB_PATH = os.environ.get("WAREHOUSE_DB", "warehouse.db")
VALID_LEVELS = {"picker", "supervisor", "manager"}


@dataclass
class ZoneAccessResult:
    success: bool
    employee_id: str
    zone_id: str
    access_level: Optional[str] = None
    previous_level: Optional[str] = None
    message: str = ""


@mcp.tool()
def grant_warehouse_zone_access(employee_id: str, zone_id: str, access_level: str, granted_by: str) -> ZoneAccessResult:
    level = access_level.strip().lower()
    if level not in VALID_LEVELS:
        return ZoneAccessResult(False, employee_id, zone_id, message=f"invalid access level: {access_level}")

    conn = sqlite3.connect(DB_PATH)
    try:
        zone = conn.execute("SELECT 1 FROM zones WHERE id = ?", (zone_id,)).fetchone()
        if zone is None:
            return ZoneAccessResult(False, employee_id, zone_id, message="zone not found")

        employee = conn.execute("SELECT 1 FROM employees WHERE id = ?", (employee_id,)).fetchone()
        if employee is None:
            return ZoneAccessResult(False, employee_id, zone_id, message="employee not found")

        approver = conn.execute(
            "SELECT access_level FROM zone_access WHERE employee_id = ? AND zone_id = ?",
            (granted_by, zone_id),
        ).fetchone()
        if approver is None or approver[0] != "manager":
            return ZoneAccessResult(False, employee_id, zone_id, message="approver is not a manager of this zone")

        existing = conn.execute(
            "SELECT access_level FROM zone_access WHERE employee_id = ? AND zone_id = ?",
            (employee_id, zone_id),
        ).fetchone()
        previous = existing[0] if existing else None

        conn.execute(
            "INSERT INTO zone_access (employee_id, zone_id, access_level, granted_by) "
            "VALUES (?, ?, ?, ?) "
            "ON CONFLICT(employee_id, zone_id) DO UPDATE SET "
            "access_level = excluded.access_level, granted_by = excluded.granted_by",
            (employee_id, zone_id, level, granted_by),
        )
        conn.commit()
    finally:
        conn.close()

    return ZoneAccessResult(True, employee_id, zone_id, level, previous, "access granted")

import os
import sqlite3

DB_PATH = os.environ.get("WAREHOUSE_DB", "warehouse.db")


def revoke_employee_warehouse_access(employee_id: str) -> dict:
    conn = sqlite3.connect(DB_PATH)
    try:
        exists = conn.execute("SELECT 1 FROM employees WHERE id = ?", (employee_id,)).fetchone()
        if exists is None:
            return {"success": False, "error": "employee not found"}

        zones_cur = conn.execute("DELETE FROM zone_access WHERE employee_id = ?", (employee_id,))
        tokens_cur = conn.execute("DELETE FROM scanner_tokens WHERE employee_id = ?", (employee_id,))
        conn.commit()
        result = {
            "success": True,
            "employee_id": employee_id,
            "zone_entries_removed": zones_cur.rowcount,
            "tokens_deleted": tokens_cur.rowcount,
        }
    except sqlite3.Error as exc:
        conn.rollback()
        result = {"success": False, "error": str(exc)}
    finally:
        conn.close()
    return result
